EDITORIAL_BAN = ["network breathes", "not a conversation", "wrong by construction", "tight cycle",
                 "workhorse", "dissolving", "boundaries are tested", "teaches padding", "paying off",
                 "buys nothing", "honest use", "informal lanes", "honesty rule", "dying quietly",
                 "which is the point", "the one idea", "here is the trap", "keeps it honest"]


def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    import re as _re
    blob = json.dumps({"l": lessons, "q": questions}, ensure_ascii=False)
    if "ERPNext" in blob:
        problems.append(f"  {name}: ERPNext branding leakage")
    if _re.search(r"\b[Ll]aws?\b", blob):
        problems.append(f"  {name}: 'law' register leakage")
    low = blob.lower()
    for marker in ["certified professional", "the consultant", "consultants", "the academy",
                   "this academy", "engagement", "constitution", "costume", "scar tissue",
                   "witness", "testimony"] + EDITORIAL_BAN:
        if marker in low:
            problems.append(f"  {name}: banned phrase '{marker}'")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.185.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.184.0"' not in init:
        sys.exit("ABORT: not at v3.184.0.")
    if "advanced_inventory" not in data:
        sys.exit("ABORT: advanced_inventory module not found in data file.")

    problems = _validate("INV8", LESSONS_I8, QUESTIONS_I8, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    bank = rebalance(list(QUESTIONS_I8))
    dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
    if max(dist.values()) > 10:
        print(f"ABORT — INV8 spread failed: {dist}")
        sys.exit(1)
    total = sum(len(l["html"]) for l in LESSONS_I8)
    print(f"INV 8 v3: {len(LESSONS_I8)} chapters ({total:,} chars, min {min(len(l['html']) for l in LESSONS_I8):,}), bank {len(bank)}, spread {dist}")

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    # residual editorial fix in counting (pre-bar pass): flatten 'paying off'
    cblob = json.dumps(data["counting"]["lessons"], ensure_ascii=False)
    fixes = [
        ("the transit warehouse holds the in-motion stock cleanly \u2014 module 2's design paying off at count time",
         "the transit warehouse holds the in-motion stock cleanly, per module 2's design"),
        ("and takes minutes, which is the point: a control that costs minutes daily runs; the control that costs a weekend quarterly gets postponed",
         "and takes minutes: a control that costs minutes daily is run consistently, while a control that requires a full weekend each quarter is postponed"),
    ]
    n = 0
    for resid, fixed in fixes:
        if resid in cblob:
            cblob = cblob.replace(resid, fixed)
            n += 1
    if n:
        data["counting"]["lessons"] = json.loads(cblob)
        print(f"  counting: {n} residual editorial phrase(s) flattened")

    data["advanced_inventory"]["lessons"] = LESSONS_I8
    data["advanced_inventory"]["questions"] = bank
    data["advanced_inventory"]["desc"] = ("Settings, roles, and structure in ZhiftERP inventory: the Stock Settings walk — negative stock off, the freeze controls, tolerances with named exception roles, and reorder automation only on data-set levels — with the annual owner review; the stock control register with its row format and quarterly confirmation; the item lifecycle — the creation gate with the duplicate check, change governance, and the four-step retirement flow; the consolidated role matrix, the quarterly recertification, and the monthly adjustments read; the filing map, retention, the retrieval test, and the handover files; multi-company structure with the inter-company document rule; and the track recap of the eight module rules.")

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.184.0"', '"3.185.0"'))
    print("  data: INVENTORY 8 lessons + bank REPLACED (style v3, formal manual register)")
    print("  INVENTORY TRACK COMPLETE (8/8)")
    print("wrote __version__ -> 3.185.0")


if __name__ == "__main__":
    main()
